/// The shipped v1.71 address of the object at reference-ELF address `p` (`None` outside the known globals
/// and DTCM tables).
pub fn to_shipped(p: CPtr) -> Option<u32> {
    SHIPPED_GLOBALS
        .iter()
        .chain(SHIPPED_TABLES.iter())
        .find(|&&(a, n, _)| p >= a && p < a + n)
        .map(|&(a, _, s)| s + (p - a))
}

/// The DTCM tables (initialised RAM, read only in practice) that a modified pointer can reach:
/// (reference ELF address, size, shipped v1.71 address). `transientVolumeTable` has no recovered shipped
/// address. Read through `cptr_*` by `memmap::table_byte`.
pub const SHIPPED_TABLES: &[(CPtr, u32, u32)] = &[
    (ADDR_transientData, 26460, 0x20000000),
    (ADDR_sine_table, 8194, 0x20006870),
    (ADDR_table_1n914, 1028, 0x20008878),
    (ADDR_ecc83Table, 1032, 0x20008c80),
];

/// The reference-ELF address of the object at shipped v1.71 address `s` (`None` outside the known globals
/// and DTCM tables).
pub fn from_shipped(s: u32) -> Option<CPtr> {
    SHIPPED_GLOBALS
        .iter()
        .chain(SHIPPED_TABLES.iter())
        .find(|&&(_, n, b)| s >= b && s < b + n)
        .map(|&(a, _, b)| a + (s - b))
}

/// The reference-ELF address of the byte `off` bytes past the object at ELF address `p`, counted in the
/// shipped v1.71 layout (for out-of-range C array indices; `None` when that byte is not modelled).
pub fn shipped_offset(p: CPtr, off: u32) -> Option<CPtr> {
    from_shipped(to_shipped(p)?.wrapping_add(off))
}
